require_once __DIR__.'/../../includes/layout.php';require_role(['Student','Teacher','Admin']);check_csrf();$id=(int)($_GET['id']??0);$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{if(($_POST['action']??'')==='create')$id=facility_create($_POST);else facility_update($id,$_POST);set_flash('success','Reservation saved. Check its current approval status.');redirect('facilities.php?id='.$id);}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$booking=$id?facility_booking($id):null;if($id&&!$booking){http_response_code(404);exit('Reservation not found.');}$u=current_user();$resources=rows('SELECT r.* FROM campus_resources r JOIN campus_offices o ON o.id=r.office_id WHERE r.active=1 AND o.active=1 ORDER BY r.name');render_header('Facility reservations'); ?>
<div class="page-title"><div><span class="eyebrow">CAMPUS SPACES</span><h1>Facility reservations</h1><p>Reserve school rooms, laboratories, and equipment. All times use Asia/Manila.</p></div><a class="btn btn-outline-primary" href="facilities.php">Calendar & reservations</a></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if($booking): ?><section class="panel"><h2><?= e($booking['resource_name']) ?></h2><p><strong><?= e($booking['status']) ?></strong></p><p><?= e(campus_time($booking['starts_at']).' → '.campus_time($booking['ends_at'])) ?></p><p class="campus-preserve"><?= e($booking['purpose']) ?></p><p><?= e($booking['staff_note']) ?></p><?php if(in_array($booking['status'],['Pending','Approved'],true)&&strtotime($booking['starts_at'].' UTC')>time()):if((int)$booking['owner_id']===(int)$u['id']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="revision" value="<?= (int)$booking['revision'] ?>"><button name="action" value="cancel" class="btn btn-outline-danger">Cancel my reservation</button></form><?php elseif(can_review_step($booking)): ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="review"><input type="hidden" name="revision" value="<?= (int)$booking['revision'] ?>"><label for="booking-decision">Office decision</label><select id="booking-decision" name="status" class="form-select" required><option value="">Choose decision</option><?php if($booking['status']==='Pending'): ?><option value="Approved">Approve reservation</option><option value="Rejected">Reject reservation</option><?php endif; ?><option value="Cancelled">Cancel reservation</option></select><label>Reason / instructions<textarea name="note" class="form-control" maxlength="600" rows="3"></textarea></label><button class="btn btn-primary">Save decision</button></form><?php endif;endif; ?></section><section class="panel"><h2>Reservation history</h2><?php foreach(rows('SELECT e.*,u.full_name FROM campus_booking_events e JOIN users u ON u.id=e.actor_id WHERE booking_id=? ORDER BY e.id',[$id]) as $event): ?><article class="campus-event"><strong><?= e($event['full_name']) ?></strong><p><?= e($event['body']) ?></p><small><?= e(campus_time($event['created_at'])) ?></small></article><?php endforeach; ?></section>
<?php else:$date=(string)($_GET['date']??date('Y-m-d'));$day=DateTimeImmutable::createFromFormat('!Y-m-d',$date,new DateTimeZone('Asia/Manila'));if(!$day||$day->format('Y-m-d')!==$date)$day=new DateTimeImmutable('today');$from=$day->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$to=$day->modify('+1 day')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$slots=rows('SELECT b.starts_at,b.ends_at,b.status,r.name FROM campus_bookings b JOIN campus_resources r ON r.id=b.resource_id WHERE b.status IN("Pending","Approved") AND b.starts_at<? AND b.ends_at>? ORDER BY b.starts_at',[$to,$from]); ?>
<div class="row g-4"><div class="col-lg-5"><section class="panel"><h2>New reservation</h2><?php if(!$resources): ?><p>The school has not made any facilities available yet.</p><?php else: ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="create"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(16)) ?>"><label for="booking-resource">Facility</label><select id="booking-resource" name="resource_id" class="form-select" required><?php foreach($resources as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['name'].' · '.$r['kind'].' · '.$r['location']) ?></option><?php endforeach; ?></select><label>Start (Manila)<input type="datetime-local" name="starts_at" class="form-control" required></label><label>End (Manila)<input type="datetime-local" name="ends_at" class="form-control" required></label><label>Purpose<textarea name="purpose" class="form-control" minlength="5" maxlength="1000" rows="3" required></textarea></label><p>Pending and approved reservations hold the time slot. Choose a future start within 90 days and up to eight hours.</p><button class="btn btn-primary">Submit reservation</button></form><?php endif; ?></section></div><div class="col-lg-7"><section class="panel"><h2>Daily availability calendar</h2><form method="get" class="campus-form"><label>Calendar date<input type="date" name="date" value="<?= e($day->format('Y-m-d')) ?>" class="form-control" required></label><button class="btn btn-outline-primary">View day</button></form><p class="mt-3">Reserved intervals are shown below. Requester names and purposes are private. Availability is checked again when submitting.</p><?php if(!$slots): ?><p>No pending or approved reservations for this date.</p><?php endif;foreach($slots as $slot): ?><article class="campus-event"><strong><?= e($slot['name']) ?></strong><p><?= e(campus_time($slot['starts_at']).' → '.campus_time($slot['ends_at']).' · '.$slot['status']) ?></p></article><?php endforeach; ?></section></div></div>
<section class="panel"><h2>My reservations & assigned reviews</h2><?php $mine=rows('SELECT b.*,r.name FROM campus_bookings b JOIN campus_resources r ON r.id=b.resource_id JOIN campus_offices o ON o.id=r.office_id WHERE ('.facility_booking_scope().') ORDER BY b.starts_at DESC LIMIT 100');if(!$mine)empty_state('No reservations yet');foreach($mine as $b): ?><article class="campus-event"><strong><?= e($b['name'].' · '.$b['status']) ?></strong><p><?= e(campus_time($b['starts_at'])) ?></p><a href="?id=<?= (int)$b['id'] ?>">Open reservation →</a></article><?php endforeach; ?></section><?php endif;render_footer(); ?>
